export const LOCAL_KEY='atlas-observatorio-research-v1';
const TABLE='atlas_dev_research';
const copy=v=>JSON.parse(JSON.stringify(v));
export function cleanResearch(raw={}){
 raw=raw&&typeof raw==='object'?raw:{};
 return {tracking:{lastSeen:typeof raw.tracking?.lastSeen==='string'&&Number.isFinite(Date.parse(raw.tracking.lastSeen))?raw.tracking.lastSeen:null},title:typeof raw.title==='string'?raw.title.slice(0,150):'Nueva historia',events:Array.isArray(raw.events)?raw.events.filter(e=>e&&typeof e.id==='string'&&typeof e.title==='string'&&typeof e.url==='string'&&typeof e.date==='string'&&Number.isFinite(Date.parse(e.date))).slice(0,100).map(e=>({...e,links:Array.isArray(e.links)?e.links.filter(l=>l&&typeof l.url==='string'&&typeof l.name==='string'):[]})):[],...Object.fromEntries(['facts','hypotheses','questions'].map(k=>[k,typeof raw[k]==='string'?raw[k].slice(0,50000):'']))};
}
export function createResearchStore({db,storage,enabled=true,onDocument=()=>{},onList=()=>{},onStatus=()=>{}}){
 let local=cleanResearch({title:'Eventos naturales y territorio'});try{local=cleanResearch(JSON.parse(storage.getItem(LOCAL_KEY))||local);}catch{}
 let uid=null,epoch=0,rows=[],active='local',dirty=new Map(),serial=0,job=null,timer,conflict=null,loaded=false;
 const status=(text,kind='info')=>onStatus(text,kind);
 const draftKey=()=>`atlas-dev-research-pending:${uid}`;
 const unpack=row=>cleanResearch({title:row.title,...row.body});
 const current=()=>active==='local'?copy(local):copy(dirty.get(active)?.doc||unpack(rows.find(r=>r.id===active)||{}));
 function list(){onList({rows:rows.map(r=>({id:r.id,title:dirty.get(r.id)?.doc.title||r.title,archived:r.archived,doc:copy(dirty.get(r.id)?.doc||unpack(r))})),active,uid,loaded,conflict,pending:dirty.size});}
 function show(){onDocument(current());list();}
 function backup(){if(!uid)return;try{if(dirty.size)storage.setItem(draftKey(),JSON.stringify([...dirty]));else storage.removeItem(draftKey());}catch{status('No se pudo respaldar el borrador local. Mantén esta pestaña abierta o exporta tu historia.','error');}}
 async function flush(){
 clearTimeout(timer);if(job)return job;if(!uid||!enabled||!dirty.size)return !dirty.size;if(conflict){status('Hay cambios de otro dispositivo. Guarda tu versión como otra historia para conservar ambas.','conflict');return false;}
 const user=uid,token=epoch;
 job=(async()=>{while(dirty.size&&uid===user&&epoch===token){const [id,draft]=dirty.entries().next().value;const sent=copy(draft);if(!sent.doc.title.trim()){status('Escribe un título para sincronizar.','error');return false;}status('Guardando en tu cuenta…','saving');
 try{const {title,...body}=sent.doc;const {data,error}=await db.from(TABLE).update({title:title.trim(),body}).eq('id',id).eq('user_id',user).eq('version',sent.version).select();if(token!==epoch)return false;if(error)throw error;if(!data?.length){conflict=id;status('Esta historia cambió en otro dispositivo. Tu borrador se conserva; guarda una copia para resolverlo.','conflict');list();return false;}
 const row=data[0];rows=rows.map(r=>r.id===id?row:r);const latest=dirty.get(id);if(latest?.serial===sent.serial)dirty.delete(id);else if(latest)latest.version=row.version;backup();list();
 }catch{if(token===epoch){status('No se pudo sincronizar. Borrador conservado en este navegador; usa Reintentar.','error');list();}return false;}}
 if(token===epoch)status('Guardado en tu cuenta · disponible en PC y móvil.','saved');return true;
 })();try{return await job;}finally{job=null;}
 }
 function change(doc){if(active==='local'){local=cleanResearch(doc);try{storage.setItem(LOCAL_KEY,JSON.stringify(local));status('Guardado anterior de este navegador guardado. Usa Guardar local en mi cuenta para sincronizarlo.','local');}catch{status('No se pudo guardar localmente. Exporta para conservar tus cambios.','error');}return;}
 const row=rows.find(r=>r.id===active);if(!row||!uid)return;const prior=dirty.get(active);dirty.set(active,{doc:cleanResearch(doc),version:prior?.version||row.version,serial:++serial});backup();status('Cambios pendientes de sincronización…','saving');list();clearTimeout(timer);timer=setTimeout(flush,650);
 }
 async function refresh(){if(!uid||!enabled)return false;if(dirty.size&&!await flush())return false;const token=epoch;try{const {data,error}=await db.from(TABLE).select('*').eq('user_id',uid).order('updated_at',{ascending:false}).limit(100);if(token!==epoch)return false;if(error)throw error;rows=data||[];loaded=true;if(active!=='local'&&!rows.some(r=>r.id===active))active='local';show();status(active==='local'?'Guardado anterior de este navegador · selecciona o crea una historia de tu cuenta.':'Sincronizado con tu cuenta de Convergencia.','saved');return true;}catch{if(token===epoch)status('No se pudieron cargar tus historias. Reintenta cuando tengas conexión.','error');return false;}}
 async function session(user){const next=enabled&&user&&!user.is_anonymous?user.id:null;if(next===uid)return;backup();epoch++;clearTimeout(timer);uid=next;rows=[];active='local';dirty=new Map();conflict=null;loaded=false;show();if(!uid){status('Ingresa con Convergencia para guardar tus historias en PC y móvil.','local');return;}
 try{const saved=JSON.parse(storage.getItem(draftKey())||'[]');for(const [id,d] of saved)if(typeof id==='string'&&Number.isInteger(d.version)&&d.doc){dirty.set(id,{...d,doc:cleanResearch(d.doc),serial:++serial});}}catch{}
 // Fetch first without discarding drafts; compare-and-swap will protect any remote changes.
 const token=epoch;status('Cargando historias de tu cuenta…','saving');try{const {data,error}=await db.from(TABLE).select('*').eq('user_id',uid).order('updated_at',{ascending:false}).limit(100);if(token!==epoch)return;if(error)throw error;rows=data||[];loaded=true;for(const [id,d] of dirty)if(!rows.some(r=>r.id===id))rows.push({id,title:d.doc.title,body:d.doc,version:d.version,archived:false});active=dirty.keys().next().value||rows.find(r=>!r.archived)?.id||'local';show();if(dirty.size)await flush();else status(active==='local'?'Tu cuenta está lista. Sigue una historia desde Noticias o Mapa.':'Sincronizado con tu cuenta de Convergencia.','saved');}catch{if(token===epoch)status('No se pudieron cargar tus historias. Tu guardado anterior de este navegador sigue disponible.','error');}
 }
 async function choose(id){if(id===active)return true;if(!await flush())return false;if(id!=='local'&&!rows.some(r=>r.id===id))return false;active=id;conflict=null;show();status(active==='local'?'Guardado anterior de este navegador · no se sincroniza hasta guardarlo en tu cuenta.':'Historia de tu cuenta de Convergencia.','info');return true;}
 let creating=false;
 async function create(doc,{resolveConflict=false,id=crypto.randomUUID()}={}){if(!uid||!loaded){status('Ingresa y carga tu cuenta antes de crear una historia.','error');return false;}if(creating)return false;if(!resolveConflict&&!await flush())return false;creating=true;const token=epoch,old=active;const value=cleanResearch(doc);if(!value.title.trim()){creating=false;return false;}
 try{const {title,...body}=value;const {data,error}=await db.from(TABLE).insert({id,title:title.trim(),body}).select();if(token!==epoch)return false;if(error?.code==='23505'){await refresh();return choose(id);}if(error||!data?.length)throw error||Error();rows.unshift(data[0]);if(resolveConflict){dirty.delete(old);conflict=null;backup();}active=data[0].id;show();status('Historia guardada en tu cuenta · disponible en PC y móvil.','saved');return true;}catch{if(token===epoch)status('No se pudo crear la historia. Revisa la conexión y reintenta (máximo 100 por cuenta).','error');return false;}finally{creating=false;}}
 async function archive(){if(active==='local'||!uid||!await flush())return false;const id=active,row=rows.find(r=>r.id===id),token=epoch;try{const {data,error}=await db.from(TABLE).update({archived:!row.archived}).eq('id',id).eq('user_id',uid).eq('version',row.version).select();if(token!==epoch)return false;if(error||!data?.length)throw error||Error();rows=rows.map(r=>r.id===id?data[0]:r);show();status(data[0].archived?'Seguimiento pausado. Puedes retomarlo desde Ver pausadas.':'Volviste a seguir esta historia.','saved');return true;}catch{status('No se pudo cambiar el archivo. Sincroniza antes de reintentar.','error');return false;}}
 return {current,change,flush,refresh,session,choose,create,archive,local:()=>copy(local),get active(){return active;},get uid(){return uid;},get pending(){return dirty.size;},get conflict(){return conflict;},start(){show();status('Ingresa con Convergencia para guardar tus historias en PC y móvil.','local');}};
}
